class ReturnThisDetector : Detector(), SourceCodeScanner {
    override fun getApplicableUastTypes() = listOf(UMethod::class.java)

    override fun createUastHandler(context: JavaContext) = object : UElementHandler() {
        override fun visitMethod(node: UMethod) {
            if (node.isConstructor) return
            val returnType = node.returnType ?: return // void? skip? Actually if void can't return this. But if annotated super, method must return this, so returnType should not be void. If void, report? We'll skip if returnType null? In Kotlin maybe Unit. Let's handle.
            val superMethods = node.findSuperMethods(true)
            val requiresReturnThis = superMethods.any { superMethod ->
                superMethod.annotations.any { it.qualifiedName?.endsWith(".ReturnThis") == true || it.name == "ReturnThis" }
            } || node.annotations.any { ... }
            if (!requiresReturnThis) return

            val body = node.uastBody ?: return
            if (!returnsThis(body)) {
                context.report(ISSUE, context.getNameLocation(node), "Method overrides a method annotated @ReturnThis and must return `this`")
            }
        }
    }

    private fun returnsThis(body: UExpression): Boolean {
        return when (body) {
            is UReturnExpression -> body.returnExpression is UThisExpression
            is UBlockExpression -> {
                val returns = body.expressions.filterIsInstance<UReturnExpression>()
                if (returns.isEmpty()) false else returns.all { it.returnExpression is UThisExpression }
            }
            else -> false
        }
    }

    companion object {
        val ISSUE = Issue.create(
            id = "ReturnThis",
            briefDescription = "Method must return `this`",
            explanation = """
                Methods that override a method annotated with `@ReturnThis` must return `this`.
                This is typically used in builder or fluent API methods.
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.ERROR,
            implementation = Implementation(ReturnThisDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )
    }
}

